{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Hydrocortisone has an absolute oral bioavailability of 0.95 in healthy adults, directly supporting F >= 20%."
    },
    {
      "card_ids": ["C18"],
      "claim": "Amoxicillin has an absolute oral bioavailability of 77.4% versus IV in healthy subjects, supporting F >= 20%."
    },
    {
      "card_ids": ["C14"],
      "claim": "Naltrexone has a systemic oral bioavailability of only 5-6% in healthy volunteers, providing the main contradictory low-F evidence."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C14"],
  "decision_summary": "Nine of ten transferred molecules show absolute oral bioavailability at or above 20%, with several well above threshold; only naltrexone is predominantly low. The high prediction is better supported, with moderate confidence due to the naltrexone conflict and formulation variability.",
  "evidence_gaps": [
    "Molecule 3 contains a record for 'finasartan' (C63) that is inconsistent with the other finasteride records; it was discounted as a provenance conflict.",
    "Molecule 10 has conflicting bioavailability estimates ranging from 5% to 40%, creating uncertainty around the low-F evidence.",
    "Some records involve altered formulations such as suspensions, PEG vehicles, or P-glycoprotein inhibitor coadministration that may not reflect standard oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C27", "C18"],
  "revision_action": "initial",
  "supportive_card_ids": ["C27", "C18"]
}

